import{z as s,x as o,o as a,c as n,q as B,j as l,D as A,d as r,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"RLVR 的设计空间","description":"","frontmatter":{"title":"RLVR 的设计空间","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlvr-design-space.md","filePath":"llm/rlvr-design-space.md","lastUpdated":1791413859000}'),D={name:"llm/rlvr-design-space.md"};function p(d,E,C,m,F,R){const e=o("Mermaid");return a(),n("div",null,[E[2]||(E[2]=B('<h1 id="rlvr-的设计空间" tabindex="-1">RLVR 的设计空间 <a class="header-anchor" href="#rlvr-的设计空间" aria-label="Permalink to &quot;RLVR 的设计空间&quot;">​</a></h1><div class="epigraph"><p>RLVR 不是单一方法，而是一组选择：验什么域、判据写多严、信号切多细——每一格既是能力边界，也是泄露面。</p><footer>—— 据 Lambert 等 Tülu 3；DeepSeek-AI R1 整理</footer></div><p><a href="/llm/verifier-bottleneck">上一课</a>把「回路上限由验证质量决定」落成假阳放大的因果链，并指出堵假阳与减假阴互相顶。本课把结论落回 <a href="/llm/rlvr">RLVR</a> 的设计表。分工先说清：那课讲机制——验证器替换 RM、PPO 与价值头、\\(\\alpha=10\\) 与 \\(\\beta\\) 的相对尺度；本课讲设计权衡——可验证域怎么选、判据的漏洞怎么治理、验证粒度怎么切。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设计空间三个轴，每个轴同时定义能力与风险。域轴：只有存在程序真值的任务能进 RLVR——数学答案、单元测试、格式约束。选域就是选能力：策略改进集中在被验证的分布上，域外不动；Tulu 3 的实测口径是目标域分升、总平均不保证升。泄露轴：判据是程序，程序有最短路径——答案正则匹配、约束满足而内容空洞、硬编码训练测例；泄露面等于判据没写明的每一个维度。粒度轴：终点 0/1、组内通过率、逐步 PRM 三档——粗粒度样本效率低且全对全错组无梯度，细粒度引入过程黑客与终点错位。</p><p><span class="marginnote">格式域的典型泄露：IFEval 式约束谓词（「恰好三段」「不得出现某词」）可以被完全满足而内容空洞。谓词只验证形式，写题时没写明「内容须切题」，策略就只优化形式。</span></p><p><span class="marginnote">「RLVR」（可验证奖励的强化学习）翻译成大白话：不用学出来的打分模型，改用写死的程序判对错——数学题对答案、代码跑测试、格式查正则。验证器是程序，所以「暂时分不出对错」的开放任务（这篇散文写得好不好）进不了这个圈子，这是能力边界也是安全边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐轴列权衡。域：窄域信号干净但能力窄；宽域靠多验证器拼装，每拼一个多一面泄露。各域堵法不同——代码域靠隐藏与随机化测例，数学域靠等价规范与同源脚本（两门验证器课的结论），格式域必须配内容判据或抽样复核。粒度：默认先终点后过程——终点信号便宜且无过程标签偏差；PRM 何时上，由题目难度与样本预算决定（Lightman 的口径：Best-of-\\(N\\) 下 PRM 与 ORM 的间隙随 \\(N\\) 加宽，难题上过程信号才显值）。判据审计：每个 \\(v\\) 配一组作弊探针——故意构造满足判据但答案错的样本，检查 \\(v\\) 是否给分；探针进回归测试，判据一改就重跑。</p><p><span class="marginnote">常见误区：初学者容易以为「信号越细越好」，上了 PRM 就万事大吉——实际上过程合法不蕴含终点正确：每一步看着都对、最后答案错，过程分照样给高。粗粒度的终点信号虽笨，却直接对准你真正关心的目标，所以默认先终点后过程。</span></p>',10)),(a(),l(i,null,{default:A(()=>[t(e,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E5%9F%9F%E8%BD%B4%EF%BC%9A%E6%95%B0%E5%AD%A6%20%2F%20%E4%BB%A3%E7%A0%81%20%2F%20%E6%A0%BC%E5%BC%8F%22%5D%20--%3E%20WIDE%5B%22%E5%9F%9F%E8%B6%8A%E5%AE%BD%EF%BC%9A%E8%83%BD%E5%8A%9B%E9%9D%A2%E8%B6%8A%E5%A4%A7%EF%BC%8C%E6%B3%84%E9%9C%B2%E9%9D%A2%E8%B6%8A%E5%A4%A7%22%5D%0A%20%20LEAK%5B%22%E6%B3%84%E9%9C%B2%E8%BD%B4%EF%BC%9A%E5%88%A4%E6%8D%AE%E4%B8%A5%E5%BA%A6%22%5D%20--%3E%20TIGHT%5B%22%E5%88%A4%E6%8D%AE%E8%B6%8A%E4%B8%A5%EF%BC%9A%E5%81%87%E9%98%B3%E8%B6%8A%E5%B0%91%EF%BC%8C%E5%81%87%E9%98%B4%E8%B6%8A%E5%A4%9A%22%5D%0A%20%20GRAN%5B%22%E7%B2%92%E5%BA%A6%E8%BD%B4%EF%BC%9A%E7%BB%88%E7%82%B9%20%2F%20%E9%80%9A%E8%BF%87%E7%8E%87%20%2F%20%E9%80%90%E6%AD%A5%22%5D%20--%3E%20FINE%5B%22%E7%B2%92%E5%BA%A6%E8%B6%8A%E7%BB%86%EF%BC%9A%E6%A0%B7%E6%9C%AC%E6%95%88%E7%8E%87%E8%B6%8A%E9%AB%98%EF%BC%8C%E8%BF%87%E7%A8%8B%E9%BB%91%E5%AE%A2%E8%B6%8A%E5%A4%9A%22%5D%0A%20%20WIDE%20--%3E%20AUD%5B%22%E4%BD%9C%E5%BC%8A%E6%8E%A2%E9%92%88%E4%B8%8E%20held-out%20%E9%87%91%E6%A0%87%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20TIGHT%20--%3E%20AUD%0A%20%20FINE%20--%3E%20AUD%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三轴互相锁。判据从严压假阳、抬假阴——即上一课的覆盖损失；域扩宽稀释单域信号——同样的 KL 预算摊到更多任务，每域推进变慢；粒度变细降低单次假阳损失，但 PRM 的过程标签偏差引入新的错位（<a href="/llm/process-supervision">过程监督</a>课：过程合法不蕴含终点正确）。所以 RLVR 设计不是找全局最优，而是把不可避免的误差堆到代价最小的轴上：高价值域接受严判据的假阴，覆盖优先时接受宽域的泄露面并加重审计。R1 的路线是另一种落子：单域数学代码、规则奖励、<a href="/llm/grpo">GRPO</a> 组采样、小 KL——粒度轴留粗，靠长链探索补样本效率；Tulu 3 把粒度交给价值头。两份配方落在同一设计空间的不同格子，不是谁对谁错。</p><p><span class="marginnote">数字实例看判据严松的两难：判据放宽后假阳率从 1% 升到 10%，一批 1000 个响应里就有 100 个「错题领奖」；收紧到假阳 0.1%，又可能错杀 5% 的正确答案（假阴），可学的信号变稀。没有两全，只有把误差堆到代价最小的那根轴上。</span></p>',3)),(a(),l(i,null,{default:A(()=>[t(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22R1%20%E9%85%8D%E6%96%B9%22%5D%20--%3E%20R1D%5B%22%E5%9F%9F%EF%BC%9A%E5%8D%95%E5%9F%9F%E6%95%B0%E5%AD%A6%20%2F%20%E4%BB%A3%E7%A0%81%22%5D%0A%20%20R1%20--%3E%20R1L%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E8%A7%84%E5%88%99%E5%A5%96%E5%8A%B1%EF%BC%8C%E4%BB%8E%E4%B8%A5%22%5D%0A%20%20R1%20--%3E%20R1G%5B%22%E7%B2%92%E5%BA%A6%EF%BC%9A%E7%BB%88%E7%82%B9%E7%B2%97%E7%B2%92%E5%BA%A6%20%2B%20%E5%B0%8F%20KL%22%5D%0A%20%20R1G%20--%3E%20R1C%5B%22%E9%9D%A0%E9%95%BF%E9%93%BE%E6%8E%A2%E7%B4%A2%E8%A1%A5%E6%A0%B7%E6%9C%AC%E6%95%88%E7%8E%87%22%5D%0A%20%20T3%5B%22Tulu%203%20%E9%85%8D%E6%96%B9%22%5D%20--%3E%20T3D%5B%22%E5%9F%9F%EF%BC%9A%E5%A4%9A%E9%AA%8C%E8%AF%81%E5%99%A8%E6%8B%BC%E8%A3%85%E5%AE%BD%E5%9F%9F%22%5D%0A%20%20T3%20--%3E%20T3G%5B%22%E7%B2%92%E5%BA%A6%EF%BC%9A%E4%BA%A4%E7%BB%99%E4%BB%B7%E5%80%BC%E5%A4%B4%22%5D%0A%20%20T3D%20--%3E%20T3A%5B%22%E5%AE%BD%E5%9F%9F%E6%B3%84%E9%9C%B2%E9%9D%A2%EF%BC%9A%E5%8A%A0%E9%87%8D%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20R1C%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E8%AE%BE%E8%AE%A1%E7%A9%BA%E9%97%B4%E7%9A%84%E4%B8%8D%E5%90%8C%E6%A0%BC%E5%AD%90%EF%BC%9A%E8%90%BD%E5%AD%90%E4%B8%8D%E5%90%8C%EF%BC%8C%E6%97%A0%E5%85%B3%E5%AF%B9%E9%94%99%22%5D%0A%20%20T3A%20--%3E%20SAME%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 RLVR 的机制与超参；奖励模型域的过优化见 <a href="/llm/rm-overoptimization">RM 过优化</a>与<a href="/llm/reward-hacking-llm">奖励黑客</a>课。域轴向外的扩展有硬限制：没有程序真值的开放任务进不了 RLVR——偏好与开放式能力的判分谁来当，是下一单元循环依赖的入口。域内的题目从哪来、难度怎么排，收在本单元末课合成课程与自出题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设计空间三轴：域、泄露、粒度；每轴既是能力边界又是风险面。</li><li>选域即选能力：改进集中在被验证分布上，总平均不保证升。</li><li>判据审计配作弊探针并进回归测试；各域堵法不同：隐藏测例、同源脚本、内容复核。</li><li>三轴互相锁：设计是把误差堆到代价最小的一轴，不是找全局最优。</li><li>出处：Lambert 等 Tülu 3（arXiv:2411.15124）；DeepSeek-AI R1；Lightman 等；Zhou 等 IFEval。</li></ul>',4))])}const T=s(D,[["render",p]]);export{_ as __pageData,T as default};
